#pragma once
// Shared infrastructure for the seqtk reimplementation.
// Provides FASTA/FASTQ parsing (plain or gzipped), formatted output,
// and small shared helpers. Do not modify without coordinating.
#include <cstdio>
#include <cstdint>
#include <string>
#include <random>
#include <zlib.h>

struct SeqRecord {
    std::string name;     // up to first whitespace
    std::string comment;  // remainder of header line after the first whitespace char
    std::string seq;
    std::string qual;     // empty for FASTA
    bool is_fastq = false;
    void clear();
};

// Streaming reader for FASTA/FASTQ. path == nullptr or "-" reads stdin.
// Auto-detects gzip. Lines may be wrapped arbitrarily; records are
// re-assembled. Trailing '\r' is stripped from every line.
class SeqFile {
public:
    explicit SeqFile(const char* path);
    ~SeqFile();
    bool is_open() const { return fp_ != nullptr; }
    // Returns 1 on record, 0 on clean EOF, -2 on malformed input.
    int next(SeqRecord& r);
private:
    gzFile fp_ = nullptr;
    int lastc_ = -2;        // one-char pushback; -2 = none
    int getc();
    void ungetc(int c) { lastc_ = c; }
    // Reads one logical line (without '\n'; trailing '\r' stripped).
    // Returns false if EOF hit with nothing read.
    bool read_line(std::string& out);
};

// Print record to `out`.
// line_len <= 0: sequence on a single line; otherwise wrap at line_len.
// as_fasta: print FASTA even if qualities exist.
void print_record(FILE* out, const SeqRecord& r, int line_len, bool as_fasta);

// Complement lookup: A<->T, C<->G (both cases); everything else maps to
// the seqtk convention ('N' for non-ACGT in the forward table).
extern const char SEQTK_COMP[256];

// Reverse-complement seq in place; if qual non-null, reverse it in place.
void revcomp(std::string& seq, std::string* qual);

// The program's RNG: 64-bit Mersenne Twister, matching the reference.
// Uniform double in [0,1) drawn as (next() >> 11) * 2^-53.
double rand_uniform(std::mt19937_64& g);

// Open a plain/gzip file for reading (nullptr/"-": stdin). Returns gzFile
// or nullptr.
gzFile seqtk_gzopen(const char* path);

#include "common.h"
#include <cctype>
#include <algorithm>
#include <cstring>

void SeqRecord::clear() {
    name.clear(); comment.clear(); seq.clear(); qual.clear();
    is_fastq = false;
}

gzFile seqtk_gzopen(const char* path) {
    if (path == nullptr || strcmp(path, "-") == 0)
        return gzdopen(0, "r");
    return gzopen(path, "r");
}

SeqFile::SeqFile(const char* path) : fp_(seqtk_gzopen(path)) {}
SeqFile::~SeqFile() { if (fp_) gzclose(fp_); }

int SeqFile::getc() {
    if (lastc_ != -2) { int c = lastc_; lastc_ = -2; return c; }
    return gzgetc(fp_);
}

bool SeqFile::read_line(std::string& out) {
    out.clear();
    int c;
    bool any = false;
    while ((c = getc()) >= 0) {
        any = true;
        if (c == '\n') break;
        out.push_back((char)c);
    }
    if (!any && out.empty()) return false;
    if (!out.empty() && out.back() == '\r') out.pop_back();
    return true;
}

int SeqFile::next(SeqRecord& r) {
    r.clear();
    int c = getc();
    if (c < 0) return 0;
    if (c != '>' && c != '@') return -2;
    bool fq = (c == '@');
    // header line
    std::string line;
    read_line(line);
    size_t i = 0;
    while (i < line.size() && !isspace((unsigned char)line[i])) ++i;
    r.name = line.substr(0, i);
    if (i < line.size()) r.comment = line.substr(i + 1);
    // sequence lines
    for (;;) {
        c = getc();
        if (c < 0) { r.is_fastq = false; return r.seq.empty() && r.name.empty() ? 0 : 1; }
        if (c == '+') { // quality follows
            r.is_fastq = true;
            read_line(line); // discard '+' line content
            while (r.qual.size() < r.seq.size()) {
                if (!read_line(line)) break;
                r.qual += line;
            }
            return 1;
        }
        if (c == '>' || c == '@') { ungetc(c); r.is_fastq = fq && false; return 1; }
        ungetc(c);
        if (!read_line(line)) { return 1; }
        r.seq += line;
    }
}

const char SEQTK_COMP[256] = {
    ['A'] = 'T', ['C'] = 'G', ['G'] = 'C', ['T'] = 'A',
    ['a'] = 't', ['c'] = 'g', ['g'] = 'c', ['t'] = 'a',
    ['U'] = 'A', ['u'] = 'a',
    ['M'] = 'K', ['m'] = 'k', ['R'] = 'Y', ['r'] = 'y',
    ['W'] = 'W', ['w'] = 'w', ['S'] = 'S', ['s'] = 's',
    ['Y'] = 'R', ['y'] = 'r', ['K'] = 'M', ['k'] = 'm',
    ['V'] = 'B', ['v'] = 'b', ['H'] = 'D', ['h'] = 'd',
    ['D'] = 'H', ['d'] = 'h', ['B'] = 'V', ['b'] = 'v',
    ['N'] = 'N', ['n'] = 'n',
};

void revcomp(std::string& seq, std::string* qual) {
    std::string out;
    out.resize(seq.size());
    for (size_t i = 0; i < seq.size(); ++i) {
        unsigned char c = (unsigned char)seq[seq.size() - 1 - i];
        char d = SEQTK_COMP[c];
        out[i] = d ? d : 'N';
    }
    seq.swap(out);
    if (qual) std::reverse(qual->begin(), qual->end());
}

static void write_wrapped(FILE* out, const std::string& s, int line_len) {
    if (line_len <= 0 || (int)s.size() <= line_len) {
        fwrite(s.data(), 1, s.size(), out);
        fputc('\n', out);
        return;
    }
    size_t i = 0;
    while (i < s.size()) {
        size_t n = s.size() - i < (size_t)line_len ? s.size() - i : (size_t)line_len;
        fwrite(s.data() + i, 1, n, out);
        fputc('\n', out);
        i += n;
    }
}

void print_record(FILE* out, const SeqRecord& r, int line_len, bool as_fasta) {
    bool fastq = r.is_fastq && !as_fasta;
    fputc(fastq ? '@' : '>', out);
    fputs(r.name.c_str(), out);
    if (!r.comment.empty()) {
        fputc(' ', out);
        fputs(r.comment.c_str(), out);
    }
